using System.Text.Json;
using System.Globalization;
using System.Windows.Data;
namespace SmartLedger.App.Converters;
public sealed class AuditDisplayConverter : IValueConverter {
 static readonly Dictionary<string,string> A=new(StringComparer.OrdinalIgnoreCase) { ["LOGIN_SUCCESS"]="تسجيل دخول ناجح",["LOGIN_FAILED"]="فشل تسجيل الدخول",["LOGOUT"]="تسجيل الخروج",["CREATE"]="إنشاء سجل",["UPDATE"]="تعديل سجل",["DELETE"]="حذف سجل",["USER_CREATED"]="إنشاء مستخدم",["USER_UPDATED"]="تعديل مستخدم",["USER_DELETED"]="حذف مستخدم",["USER_ACTIVATED"]="تفعيل مستخدم",["USER_DEACTIVATED"]="تعطيل مستخدم",["PERSON_UPDATE"]="تعديل الحساب",["PERSON_CREATE"]="إنشاء الحساب",["MANUAL_BALANCE_ADJUSTMENT"]="تعديل يدوي للرصيد",["PRODUCT_UPDATE"]="تعديل بيانات/أسعار الصنف",["PRODUCT_CREATE"]="إنشاء صنف",["PRODUCT_DELETE"]="حذف صنف",["INVOICE_CREATE"]="إنشاء فاتورة",["REVERSE_INVOICE"]="عكس فاتورة",["EXPENSE_CREATE"]="تسجيل مصروف",["OPERATION_DELETE"]="حذف حركة",["TEMPLATE_SAVE"]="حفظ قالب رسالة" };
 static readonly Dictionary<string,string> E=new(StringComparer.OrdinalIgnoreCase) { ["User"]="مستخدم",["Users"]="المستخدمون",["Person"]="شخص",["Book"]="دفتر",["Operation"]="عملية",["Product"]="منتج",["StockMovement"]="حركة مخزون",["Invoice"]="فاتورة",["Expense"]="مصروف",["Settings"]="الإعدادات",["MessageTemplate"]="قالب رسالة" };
 static readonly Dictionary<string,string> EnA=new(StringComparer.OrdinalIgnoreCase) { ["LOGIN_SUCCESS"]="Successful sign-in",["LOGIN_FAILED"]="Failed sign-in",["LOGOUT"]="Sign out",["PERSON_UPDATE"]="Account updated",["PERSON_CREATE"]="Account created",["MANUAL_BALANCE_ADJUSTMENT"]="Manual balance adjustment",["PRODUCT_UPDATE"]="Product / price updated",["PRODUCT_CREATE"]="Product created",["PRODUCT_DELETE"]="Product deleted",["INVOICE_CREATE"]="Invoice created",["REVERSE_INVOICE"]="Invoice reversed",["EXPENSE_CREATE"]="Expense recorded",["OPERATION_DELETE"]="Ledger operation deleted",["TEMPLATE_SAVE"]="Message template saved",["USER_CREATED"]="User created",["USER_UPDATED"]="User updated",["USER_DELETED"]="User deleted" };
 static readonly Dictionary<string,string> EnE=new(StringComparer.OrdinalIgnoreCase) { ["User"]="User",["Users"]="Users",["Person"]="Account",["Book"]="Book",["Operation"]="Ledger operation",["Product"]="Product",["StockMovement"]="Stock movement",["Invoice"]="Invoice",["Expense"]="Expense",["Settings"]="Settings",["MessageTemplate"]="Message template" };
 public object Convert(object value,Type targetType,object parameter,CultureInfo culture) { var s=value?.ToString()??""; var k=parameter?.ToString()??""; if(string.IsNullOrWhiteSpace(s))return "—"; if(k=="Action") { var map=culture.Name.StartsWith("en",StringComparison.OrdinalIgnoreCase)?EnA:A; return map.TryGetValue(s,out var a)?a:s; } if(k=="Entity") { var map=culture.Name.StartsWith("en",StringComparison.OrdinalIgnoreCase)?EnE:E; return map.TryGetValue(s,out var e)?e:s; } if(k=="Date"){DateTimeOffset d; if(value is DateTimeOffset dto)d=dto.ToLocalTime();else if(value is DateTime dt)d=new DateTimeOffset(dt);else if(!DateTimeOffset.TryParse(s,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out d))return s;return d.ToString("dd/MM/yyyy — hh:mm tt",CultureInfo.InvariantCulture).Replace("AM","ص").Replace("PM","م");} if(k=="Details"){try{using var doc=JsonDocument.Parse(s);if(doc.RootElement.ValueKind==JsonValueKind.Object){var p=new List<string>();foreach(var x in doc.RootElement.EnumerateObject()){var label=x.Name switch {"UserName"=>"اسم المستخدم","DisplayName"=>"الاسم","Name"=>"الاسم","Id"=>"المعرّف","Reason"=>"السبب","Count"=>"العدد","Status"=>"الحالة","OldValue"=>"القيمة السابقة","NewValue"=>"القيمة الجديدة",_=>x.Name};p.Add(label+": "+(x.Value.ValueKind==JsonValueKind.String?x.Value.GetString():x.Value.GetRawText()));}return p.Count==0?"لا توجد تفاصيل إضافية":string.Join(" ؛ ",p);}return doc.RootElement.ValueKind==JsonValueKind.String?doc.RootElement.GetString()??"—":doc.RootElement.ToString();}catch{return s;}} return s; }
 public object ConvertBack(object value,Type targetType,object parameter,CultureInfo culture)=>Binding.DoNothing;
}
